-- Mera Ustaad sample data. Generated from the prototype's teacher list.
-- Teachers are seeded with their aggregate rating and review count; three sample reviews each.
-- The rating trigger is disabled while seeding so the aggregates are not overwritten.

alter table public.teacher_reviews disable trigger trg_reviews_rating;

insert into public.teachers (full_name, area, latitude, longitude, qualifications, experience_years, subjects, curricula, bio_description, teaching_approach, result_highlights, hourly_rate, home_visit_premium, estimated_monthly_salary, available_at_school, available_at_student_home, available_at_teacher_home, travel_radius_km, qualifications_verified, results_verified, rating_avg, reviews_count) values
  ('Sana Javed', 'Gulberg', 31.512, 74.348, array['MPhil HRM|LUMS','BBA (Hons)|IBA Karachi','Cambridge Teaching Award|Cambridge CIE']::text[], 11, array['Business Studies','Economics']::text[], array['O Levels','A Levels','IB']::text[], 'Business and economics teacher with eleven years across Lahore’s Cambridge and IB schools. I help students think like analysts, not just memorise definitions.', 'Case-study lessons, weekly timed essays and examiner-report feedback after every mock.', array['14 of 16 A Level Business students scored A or A* (2025)','Two IB Economics students scored 7 (2025)']::text[], 3000, 500, 180000, true, true, true, 10, true, true, 4.9, 112),
  ('Hamza Qureshi', 'DHA Phase 5', 31.466, 74.412, array['MSc Mathematics|LUMS','BS Mathematics|LUMS','Edexcel Examiner Training|Pearson']::text[], 9, array['Mathematics']::text[], array['O Levels','A Levels','IB','Matric']::text[], 'Makes maths feel logical instead of memorised. Specialises in O Level Additional Maths and A Level Pure 1 to 3.', 'Concept first, then past papers by topic. Parents get a short progress note every Sunday.', array['12 of 15 O Level Maths students moved up two grades (2025)','Average A Level P3 mock score up 21 percent in one term']::text[], 3500, 500, null, false, true, true, 10, true, true, 4.9, 148),
  ('Mariam Tariq', 'Model Town', 31.482, 74.325, array['MA English Literature|Kinnaird College','BA (Hons) English|LCWU','CELTA|Cambridge English']::text[], 12, array['English']::text[], array['O Levels','A Levels','IB','Matric']::text[], 'Twelve years teaching English Language and Literature. Strong on essay structure, comprehension and confident speaking.', 'Reads together, writes together. Every essay is returned with margin comments and one clear next step.', array['10 of 13 O Level English students scored A or above (2025)','IGCSE First Language pass rate of 100 percent across my last three batches']::text[], 2800, 400, 150000, true, true, true, 8, true, true, 4.8, 96),
  ('Usman Ghani', 'Wapda Town', 31.441, 74.269, array['MSc Physics|University of the Punjab','BSc (Hons) Physics|GC University Lahore']::text[], 9, array['Physics','Mathematics']::text[], array['Matric','FSc','O Levels']::text[], 'Patient Physics and Maths teacher. Numericals are solved step by step so students learn the method, not just the answer.', 'Short theory, long practice. Chapter tests every second week with error analysis.', array['9 of 11 FSc Physics students scored 80 percent or above (2025)','Matric board Physics average of 92 percent in my 2025 batch']::text[], 2500, 400, null, false, true, true, 8, true, true, 4.8, 86),
  ('Dr. Bilal Ahmad', 'Johar Town', 31.47, 74.272, array['PhD Chemistry|GC University Lahore','MSc Chemistry|University of the Punjab']::text[], 15, array['Chemistry','Biology']::text[], array['FSc','A Levels','Matric']::text[], 'University lecturer teaching Chemistry and Biology with lab-style demonstrations and chapter-wise tests.', 'Reaction mechanisms explained visually, with a short quiz at the start of every session.', array['Several students admitted to King Edward Medical University after FSc preparation']::text[], 3200, 0, 200000, true, false, true, 5, true, false, 4.7, 77),
  ('Hira Nadeem', 'DHA Phase 6', 31.454, 74.425, array['BSc Accounting & Finance|LUMS','ACCA Affiliate|ACCA Global']::text[], 5, array['Accounting','Economics']::text[], array['O Levels','A Levels']::text[], 'Accounting and finance graduate who turns ledgers and ratios into simple, repeatable steps.', 'Worked examples first, then timed past-paper questions marked against the mark scheme.', array['7 of 9 O Level Accounting students scored B or above (2025)']::text[], 2500, 400, null, false, true, true, 8, true, false, 4.7, 52),
  ('Imran Hashmi', 'Faisal Town', 31.482, 74.3, array['MA Urdu|University of the Punjab','B.Ed|AIOU']::text[], 14, array['Urdu','Islamiat','Pak Studies']::text[], array['Matric','FSc','O Levels']::text[], 'Fourteen years teaching Urdu grammar, essay and letter writing, plus Islamiat and Pakistan Studies notes.', 'Reading aloud, short writing tasks and clear exam-style notes.', array['Matric Urdu average of 85 percent in my 2025 batch']::text[], 1200, 300, 90000, true, true, true, 7, true, false, 4.7, 69),
  ('Fatima Zahra', 'DHA Phase 3', 31.486, 74.408, array['BA Education|Lahore College for Women University','Montessori Diploma|AMI']::text[], 7, array['English','Urdu','Mathematics']::text[], array['Primary']::text[], 'Montessori-trained and calm with young learners. Covers alphabets, reading, counting and early writing.', 'Play-based sessions with a small take-home activity so learning continues all week.', array['23 children prepared for Grade 1 entry assessments (2025)','All students reading simple paragraphs within one term']::text[], 1800, 300, null, false, true, false, 6, true, true, 4.9, 58),
  ('Ali Raza', 'Garden Town', 31.498, 74.328, array['BE Electrical Engineering|UET Lahore']::text[], 7, array['Mathematics','Physics','Computer Science']::text[], array['O Levels','Matric','FSc']::text[], 'Engineer turned tutor. Strong with algebra, geometry and Physics numericals.', 'Real-world examples, then practice sets by difficulty.', array['Most students improve a full grade within two months']::text[], 2200, 400, null, false, true, true, 6, false, false, 4.6, 55),
  ('Sadia Karim', 'Valencia', 31.404, 74.228, array['B.Ed|AIOU','BA|University of the Punjab']::text[], 6, array['Mathematics','English','Urdu']::text[], array['Primary','Middle']::text[], 'All-subject primary and middle tutor. Homework support, daily practice sheets and a monthly parent call.', 'Small steps, lots of encouragement and regular revision.', array['Consistent improvement in school test scores for most students']::text[], 1000, 200, 70000, true, true, true, 5, false, false, 4.5, 28),
  ('Amna Shahid', 'Gulberg', 31.512, 74.348, array['MPhil Chemistry|Forman Christian College','BSc (Hons) Chemistry|FCCU']::text[], 9, array['Chemistry','Biology']::text[], array['O Levels','A Levels','FSc','IB']::text[], 'Focused on exam-style answers and concept clarity in the sciences, with chapter summaries and practice tests.', 'Diagram-led revision and a mark-scheme walk-through after every test.', array['11 of 14 A Level Chemistry students scored A or A* (2025)','IB Chemistry average of 6.4 in my last batch']::text[], 3000, 500, 190000, true, true, true, 6, true, true, 4.8, 73),
  ('Faizan Butt', 'Askari 10', 31.52, 74.405, array['BS Software Engineering|UET Lahore']::text[], 3, array['Computer Science','Mathematics']::text[], array['O Levels','Matric']::text[], 'Teaches computing from first principles, with hands-on Python and logic practice.', 'Learn by building: every session ends with a small working program.', array['Students complete a first Python project within six weeks']::text[], 1800, 0, null, false, false, true, 4, false, false, 4.4, 14),
  ('Rabia Aslam', 'DHA Phase 1', 31.469, 74.388, array['MA English|Lahore College for Women University','B.Ed|University of the Punjab']::text[], 11, array['English','Urdu']::text[], array['Primary','Middle','Matric']::text[], 'Prepares children for school tests and interviews with reading practice, vocabulary building and confidence exercises.', 'Warm, structured lessons with reading logs that parents can follow.', array['31 students placed in leading Lahore schools after entry preparation (2025)','Average reading level up by two grades in one year']::text[], 2200, 300, 120000, true, true, false, 7, true, true, 4.9, 101),
  ('Maham Javed', 'DHA Phase 8', 31.44, 74.433, array['BA (Hons) Social Sciences|LUMS']::text[], 3, array['Economics','Pak Studies','Business Studies']::text[], array['O Levels','A Levels','IB']::text[], 'Helps students understand economics and history through stories, graphs and exam-style questions.', 'Graph drills, short essays and quick oral recaps.', array['Early students moved from C to B grades within a term']::text[], 2000, 300, null, false, true, true, 6, false, false, 4.5, 19),
  ('Qari Abdul Rehman', 'Model Town', 31.482, 74.325, array['Shahadat-ul-Alamiya|Jamia Ashrafia','MA Islamic Studies|University of the Punjab']::text[], 20, array['Islamiat','Urdu']::text[], array['Primary','Middle','Matric']::text[], 'Teaches Quran with tajweed, Islamiat and Urdu to children of all ages, with a focus on correct pronunciation and good adab.', 'Patient one-to-one recitation practice with weekly revision.', array['Over 150 children completed Nazra Quran with me','Matric Islamiat average of 90 percent in my 2025 batch']::text[], 1000, 200, null, false, true, true, 8, true, true, 4.9, 210),
  ('Kamran Ali', 'DHA Phase 4', 31.477, 74.425, array['MS Statistics|NUST','BSc Mathematics|LUMS']::text[], 10, array['Mathematics','Computer Science']::text[], array['A Levels','IB','FSc']::text[], 'Mathematics and statistics specialist for A Level, IB and FSc. Known for turning exam anxiety into steady habits.', 'Weekly goal sheets, timed practice and calm error analysis.', array['9 of 12 A Level Maths students scored A or A* (2025)','Two IB Maths AA HL students scored 7 (2025)']::text[], 3800, 0, 220000, true, false, true, 10, true, true, 4.8, 88);

